From d4ebe3a98ba89b3f776b22731ef18c549533a14a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 19:48:35 +0100
Subject: [PATCH] osd: add actions to extend above and below the built-in
 screen

The OSD and the applet could only put the other screen to the left or
right of the built-in one. Add actions to extend above and below it, and
let the OSD buttons shrink so that the longer row fits narrow screens.

BUG: 406377
---
 common/osdaction.cpp    | 42 +++++++++++++++++++++++++++++++++++++++++
 common/osdaction.h      |  2 ++
 osd/qml/OsdSelector.qml | 12 ++++++++++--
 3 files changed, 54 insertions(+), 2 deletions(-)

diff --git a/common/osdaction.cpp b/common/osdaction.cpp
index 0f41f2f9..0d84255b 100644
--- a/common/osdaction.cpp
+++ b/common/osdaction.cpp
@@ -29,6 +29,8 @@ QList<OsdAction> OsdAction::availableActions()
         {Clone, i18nd("kscreen_common", "Mirror screens"), QStringLiteral("osd-duplicate")},
         {ExtendLeft, i18nd("kscreen_common", "Extend to left of built-in screen"), QStringLiteral("osd-sbs-left")},
         {ExtendRight, i18nd("kscreen_common", "Extend to right of built-in screen"), QStringLiteral("osd-sbs-sright")},
+        {ExtendAbove, i18nd("kscreen_common", "Extend above built-in screen"), QStringLiteral("osd-sbs-above")},
+        {ExtendBelow, i18nd("kscreen_common", "Extend below built-in screen"), QStringLiteral("osd-sbs-below")},
         {NoAction, i18nd("kscreen_common", "Leave unchanged"), QStringLiteral("dialog-cancel")},
     };
 }
@@ -116,6 +118,46 @@ KScreen::SetConfigOperation *OsdAction::applyAction(const QSharedPointer<KScreen
         internal->setPos({copy->logicalSizeForOutputInt(*external).width(), 0});
         break;
     }
+    case KScreen::OsdAction::Action::ExtendAbove: {
+        internal->setEnabled(true);
+        external->setEnabled(true);
+        external->setPos(QPoint());
+        ModePtr currentMode = external->currentMode();
+        if (!currentMode) { // When the external display is not enabled
+            const auto externalModesMap = external->modes();
+            Q_ASSERT(!externalModesMap.empty());
+            auto bestModeIt = std::max_element(externalModesMap.cbegin(), externalModesMap.cend(), [](const auto &left, const auto &right) {
+                const QSize leftSize = left->size();
+                const QSize rightSize = right->size();
+                return (leftSize.width() < rightSize.width() && leftSize.height() < rightSize.height())
+                    || (leftSize == rightSize && left->refreshRate() < right->refreshRate());
+            });
+            currentMode = bestModeIt.value();
+            external->setCurrentModeId(currentMode->id());
+        }
+        internal->setPos({0, copy->logicalSizeForOutputInt(*external).height()});
+        break;
+    }
+    case KScreen::OsdAction::Action::ExtendBelow: {
+        internal->setEnabled(true);
+        external->setEnabled(true);
+        internal->setPos(QPoint());
+        ModePtr currentMode = internal->currentMode();
+        if (!currentMode) { // When the internal display is not enabled
+            const auto internalModesMap = internal->modes();
+            Q_ASSERT(!internalModesMap.empty());
+            auto bestModeIt = std::max_element(internalModesMap.cbegin(), internalModesMap.cend(), [](const auto &left, const auto &right) {
+                const QSize leftSize = left->size();
+                const QSize rightSize = right->size();
+                return (leftSize.width() < rightSize.width() && leftSize.height() < rightSize.height())
+                    || (leftSize == rightSize && left->refreshRate() < right->refreshRate());
+            });
+            currentMode = bestModeIt.value();
+            internal->setCurrentModeId(currentMode->id());
+        }
+        external->setPos({0, copy->logicalSizeForOutputInt(*internal).height()});
+        break;
+    }
     }
     return new KScreen::SetConfigOperation(copy);
 }
diff --git a/common/osdaction.h b/common/osdaction.h
index 1668fb48..fbaf075a 100644
--- a/common/osdaction.h
+++ b/common/osdaction.h
@@ -35,6 +35,8 @@ public:
         Clone,
         ExtendLeft,
         ExtendRight,
+        ExtendAbove,
+        ExtendBelow,
     };
     Q_ENUM(Action)

diff --git a/osd/qml/OsdSelector.qml b/osd/qml/OsdSelector.qml
index 92c4377f..3ed1b4b7 100644
--- a/osd/qml/OsdSelector.qml
+++ b/osd/qml/OsdSelector.qml
@@ -69,6 +69,13 @@ Control {
         id: content

         RowLayout {
+            id: actionRow
+
+            // Shrink the buttons on narrow screens so that all of them fit
+            readonly property real buttonWidth: root.Screen.width > 0 && actionRepeater.count > 0
+                ? Math.floor(root.Screen.width * 0.8 / actionRepeater.count) - spacing
+                : Infinity
+
             Repeater {
                 id: actionRepeater
                 property int currentIndex: 0
@@ -76,11 +83,12 @@ Control {
                 delegate: OsdButton {
                     required property var modelData
                     property int actionId: modelData.action
+                    readonly property real iconSize: Math.min(Kirigami.Units.gridUnit * 8, actionRow.buttonWidth - leftPadding - rightPadding)

                     text: modelData.label
                     icon.name: modelData.iconName
-                    icon.height: Kirigami.Units.gridUnit * 8
-                    icon.width: Kirigami.Units.gridUnit * 8
+                    icon.height: iconSize
+                    icon.width: iconSize

                     onClicked: root.clicked(actionId)
                 }
